import { uploadConfig } from './config.js'
import { parseSize } from './size.js'

// PDFs get a bigger allowance than the general per-type limit in config/upload.json.
const TYPE_MAX_OVERRIDES = { 'application/pdf': parseSize('25MB', { binary: true }) }

// file: { name, type, size (bytes) }
export function validateUpload(file) {
  if (!uploadConfig.allowedTypes.includes(file.type)) return { ok: false, status: 415, error: `Unsupported type: ${file.type}` }
  const max = TYPE_MAX_OVERRIDES[file.type] ?? parseSize(uploadConfig.maxSize, { binary: true })
  if (file.size > max) return { ok: false, status: 413, error: `File too large: max ${max / (1024 * 1024)} MiB` }
  return { ok: true }
}

test('parses sizes', () => {
  assert.equal(parseSize('512KB'), 512_000)
  assert.equal(parseSize('2 GB'), 2_000_000_000)
})

test('parses binary sizes', () => {
  assert.equal(parseSize('10MB', { binary: true }), 10_485_760)
  assert.equal(parseSize('25MB', { binary: true }), 26_214_400)
})

