test('accepts an image exactly at the 10 MiB limit', () => {
  assert.deepEqual(validateUpload({ name: 'a.jpg', type: 'image/jpeg', size: 10_485_760 }), { ok: true })
})

test('rejects an image one byte over the 10 MiB limit', () => {
  const result = validateUpload({ name: 'a.jpg', type: 'image/jpeg', size: 10_485_761 })
  assert.equal(result.status, 413)
  assert.equal(result.error, 'File too large: max 10 MiB')
})

test('accepts a PDF exactly at the 25 MiB limit', () => {
  assert.deepEqual(validateUpload({ name: 'a.pdf', type: 'application/pdf', size: 26_214_400 }), { ok: true })
})

test('rejects a PDF one byte over the 25 MiB limit', () => {
  const result = validateUpload({ name: 'a.pdf', type: 'application/pdf', size: 26_214_401 })
  assert.equal(result.status, 413)
  assert.equal(result.error, 'File too large: max 25 MiB')
})

test('rejects a non-PDF at 25 MiB, since the PDF override does not apply', () => {
